package com.careernav.service;
import com.careernav.config.AppProperties;
import com.careernav.domain.ApiModels.*;
import dev.langchain4j.model.chat.ChatLanguageModel;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.stereotype.Service;
import java.time.Duration; import java.time.LocalDateTime; import java.util.*;
@Service
public class AgentOrchestrator {
 private final ResumeService resumeService;private final JobService jobService;private final InterviewService interviewService;private final DiagnosisService diagnosisService;private final LearningPathService learningPathService;private final ObjectProvider<ChatLanguageModel> models;private final AppProperties properties;
 public AgentOrchestrator(ResumeService resumeService,JobService jobService,InterviewService interviewService,DiagnosisService diagnosisService,LearningPathService learningPathService,ObjectProvider<ChatLanguageModel> models,AppProperties properties){this.resumeService=resumeService;this.jobService=jobService;this.interviewService=interviewService;this.diagnosisService=diagnosisService;this.learningPathService=learningPathService;this.models=models;this.properties=properties;}
 public AgentRunResult run(AgentRunRequest request){long started=System.nanoTime();ResumeView resume=resumeService.get(request.resumeId());List<AgentStep> steps=new ArrayList<>();steps.add(step(steps.size()+1,"resume.profile","读取并结构化简历","已解析 "+resume.skills().size()+" 项技能、"+resume.projects().size()+" 个项目",started));long mark=System.nanoTime();List<JobRecommendation> recommendations=jobService.recommend(resume,null,5);Long jobId=request.jobId();if(jobId==null&&!recommendations.isEmpty())jobId=recommendations.getFirst().job().id();steps.add(step(steps.size()+1,"job.match","岗位图谱匹配","完成 "+recommendations.size()+" 个岗位的语义与技能匹配",mark));mark=System.nanoTime();InterviewView interview=null;if(jobId!=null){interview=interviewService.start(new InterviewStartRequest(resume.id(),jobId,request.intent()!=null&&request.intent().contains("深度")?"深度":"标准"));steps.add(step(steps.size()+1,"interview.start","创建模拟面试","围绕目标岗位生成 4 轮递进问题",mark));}mark=System.nanoTime();DiagnosisReport diagnosis=diagnosisService.diagnose(resume.id(),jobId);steps.add(step(steps.size()+1,"resume.diagnose","执行简历诊断","综合得分 "+diagnosis.overallScore()+"，识别 "+diagnosis.suggestions().size()+" 项优化建议",mark));mark=System.nanoTime();LearningPath path=learningPathService.generate(resume.id(),diagnosis.targetRole());steps.add(step(steps.size()+1,"learning.generate","生成个性化学习路线","准备度 "+path.readiness()+"%，规划 "+path.modules().size()+" 个阶段",mark));boolean llm=properties.getAgent().getApiKey()!=null&&!properties.getAgent().getApiKey().isBlank();String summary=buildSummary(resume,diagnosis,recommendations,path);if(llm)summary=enrichWithLlm(summary,diagnosis,recommendations);String mode=llm?"LangChain4j 在线模型 + 工具链":"LangChain4j 本地推理 + 工具链";return new AgentRunResult(UUID.randomUUID().toString(),"full-workflow",mode,summary,steps,diagnosis,recommendations,path,interview,LocalDateTime.now());}
 private String enrichWithLlm(String fallback,DiagnosisReport diagnosis,List<JobRecommendation> recommendations){ChatLanguageModel model=models.getIfAvailable();if(model==null)return fallback;String prompt="你是计算机学生职业发展顾问。请基于以下事实，用150字以内给出连续、可执行的规划建议。\n目标岗位："+diagnosis.targetRole()+"\n简历得分："+diagnosis.overallScore()+"\n缺失技能："+String.join("、",diagnosis.missingKeywords())+"\n推荐岗位："+recommendations.stream().limit(2).map(i->i.job().title()).toList()+"\n要求：不要编造经历，不要使用 Markdown。";try{return model.generate(prompt);}catch(Exception ignored){return fallback;}}
 private String buildSummary(ResumeView resume,DiagnosisReport diagnosis,List<JobRecommendation> recommendations,LearningPath path){String top=recommendations.isEmpty()?diagnosis.targetRole():recommendations.getFirst().job().title();String missing=diagnosis.missingKeywords().isEmpty()?"项目量化表达":String.join("、",diagnosis.missingKeywords().stream().limit(3).toList());return String.format("%s 当前简历得分 %d 分，与“%s”匹配度最高。建议优先补齐 %s，完成“%s”，用 3 次模拟面试沉淀表达证据后再次诊断。",resume.ownerName(),diagnosis.overallScore(),top,missing,path.modules().isEmpty()?"岗位技能专项":path.modules().getFirst().title());}
 private AgentStep step(int order,String tool,String title,String detail,long start){return new AgentStep(order,tool,title,"SUCCESS",Duration.ofNanos(System.nanoTime()-start).toMillis(),detail);}
}
